# 5 tracheostomy: partial after Phase 8.1 recovery (NHS GGC guideline) ----------------------------------
GGC="N-NHSGGC-TRACH-2022"
write(5,"tracheostomy-care",dict(title="Tracheostomy care", category="airway-ventilation", topic_drafts=[],
 evidence_status="partial", license_status="permission_required",
 sources=[src(GGC,"full","NHS Greater Glasgow and Clyde guideline v3 (2022; past its review date); sections read in full text; NTSP resources used there with permission"),src("S-AARC-TRACH","not_read","AARC CPG on tracheostomy (2021): cite-only, not read"),src("N-NCBI-OPENRN-TRACH","not_read","Open RN via NCBI Bookshelf NBK596713: browser-verification page; not read"),src("N-ACI-TRACH","not_read","NSW ACI guide: HTTP 403; not read"),src(ICS,"full","rec 60: tracheostomy spares for transfer")],
 objectives=["Secure the tube and check it for displacement and skin damage.","Care for the inner cannula, humidification, cuff and stoma as the unit's protocol directs.","Suction only when needed and recognise the difficult catheter pass as an emergency.","Recognise the red flags of a tracheostomy problem and use the bedhead sign and emergency algorithm."],
 prerequisites=["Suctioning (SK-06)","Endotracheal tube care (SK-04)"],
 sections={
  "indications":sec("partial",it("Patients with a tracheostomy often need suctioning to keep the airway open, and each patient needs individual assessment and constant reassessment of how often.","sourced",GGC)),
  "safety":sec("partial",it("An inadequately secured tube may become partly or completely displaced and obstruct the airway; consider partial displacement whenever the patient deteriorates or becomes distressed, because it may not be obvious.","sourced",GGC),it("Tracheostomy and laryngectomy patients have different airflow routes and are managed differently in an emergency: a patient with a laryngectomy cannot be ventilated through the nose and mouth and must be ventilated through the stoma.","sourced",GGC),it("Any difficulty passing a suction catheter should raise the possibility of a partly blocked, badly orientated or misplaced tube and needs immediate attention as an emergency.","sourced",GGC),it("Transfers between areas of patients with tracheostomies must be planned between the nursing and medical staff of both areas because unfamiliarity is a clinical risk.","sourced",GGC)),
  "responsibilities":sec("partial",it("Inner-cannula care: secretions can narrow the lumen over time, so clean the inner cannula regularly, leave it to dry rather than in water, avoid abrasive brushes, and document and communicate the reason if it is not changed. This guideline gives a minimum interval of every four hours with more frequent cleaning when secretions are heavy (local guideline value).","partial",GGC),it("Secure the tube with a tracheostomy holder or tape, check the back of the neck regularly for pressure damage, and make sure one finger fits between the tape and the skin.","sourced",GGC),it("Keep a spare inner cannula in a clean container at the bedside; some tube makers require the inner cannula in place before connecting oxygen, a circuit or a bag-valve device.","sourced",GGC)),
  "scope":sec("local_protocol",LOCAL("Who may change tubes, deflate cuffs, decannulate and suction a tracheostomy follows local policy and competence; this guideline expects staff caring for these patients to have the required training.")),
  "equipment":sec("partial",it("An emergency box stays with the patient, including during transfers, with a spare tube and inner cannula (same size and a smaller size), dilators, a means of securing the tube, suction catheters, a syringe for cuffed tubes and oxygen masks; a cuff manometer, humidification spares and the correct bedhead sign with the emergency algorithm belong at the bedside.","sourced",GGC),it("For a transfer, take tracheostomy spares in line with the National Tracheostomy Safety Project (ICS 2026 recommendation 60).","partial",ICS)),
  "assessment":sec("partial",it("Humidification must match the patient's condition and secretions, using a ladder of devices, and saline nebulisers or mucolytics and hydration are considered if secretions are not improving.","sourced",GGC),it("Inspect the stoma daily for signs of infection; keep it clean and dry; routine dressings are not recommended, and any dressing must be pre-cut and made for tracheostomy use so fibres do not enter the airway.","sourced",GGC)),
  "procedure":sec("partial",it("Suction when necessary, encouraging deep breaths and coughing first; the guideline gives example indications (noisy breathing, ineffective cough, visible or audible secretions, increased work of breathing, falling saturations) and lists the risks (hypoxia, mucosal trauma, arrhythmia, atelectasis, bronchospasm, infection, bleeding, raised intracranial pressure, interruption of ventilation).","sourced",GGC),it("If a fenestrated tube is in place, change to a non-fenestrated inner cannula before suctioning; this guideline states a catheter no wider than half the inner lumen, suction not longer than about ten seconds and a stated vacuum range (local guideline values; the unit's protocol governs).","partial",GGC),it("Cuff pressure is checked with a manometer; this guideline cites a recommended range and twice-daily checks unless more are indicated (local guideline values), and warns that too low a pressure causes a leak and micro-aspiration while over-inflation impairs tracheal blood flow.","partial",GGC)),
  "monitoring":sec("partial",it("Red flags: for a correctly sited cuffed tube no air should escape through the mouth (talking, audible leaks or bubbling saliva suggest a cuff or placement problem); apnoea on capnography, difficulty breathing, higher airway pressures, lower tidal volumes, hypoxia and noisy breathing; a visibly displaced tube, blood around the tube, new pain, or needing a lot of air to keep the cuff inflated; and any change in respiratory rate, heart rate, blood pressure or consciousness, including anxiety, restlessness or confusion.","sourced",GGC)),
  "escalation":sec("partial",it("Use the correct bedhead sign and the emergency algorithm that applies to the patient (tracheostomy with a possibly patent upper airway, or laryngectomy); capnography is essential in an emergency, and a circuit suitable for emergency ventilation is recommended. Call the emergency team urgently for a peri-arrest situation, including when a suction catheter will not pass.","sourced",GGC)),
  "complications":sec("partial",it("Risks include displacement and obstruction, bleeding, stoma skin irritation or infection, cuff-related tracheal injury and, with a low cuff pressure, aspiration and pneumonia.","partial",GGC)),
  "documentation":sec("local_protocol",LOCAL("Record safety checks, suction, oxygen and inner-cannula care on the unit's tracheostomy chart; document and explain any inner cannula that is not changed.")),
  "communication":sec("partial",it("Plan transfers with the receiving team, and keep the bedhead sign and emergency algorithm with the patient.","partial",GGC))},
 checklist=[c("preparation","Confirm the bedhead sign, emergency box, suction, oxygen and spare tube are at the bedside.",True,"sourced",GGC),c("assessment","Check the tube is secure and that one finger fits under the tape; inspect the back of the neck.",True,"sourced",GGC),c("assessment","Look and listen for red flags: air leak at the mouth, noisy breathing, displaced tube, blood around the tube, new pain.",True,"sourced",GGC),c("procedure","Clean the inner cannula as the unit's protocol directs and keep a spare in a clean container.",False,"partial",GGC),c("procedure","Suction only when needed; if the catheter will not pass, treat it as an emergency and call for help.",True,"sourced",GGC),c("monitoring","Check cuff pressure with a manometer at the unit's interval.",False,"partial",GGC),c("assessment","Inspect the stoma daily and keep it clean and dry.",False,"sourced",GGC),c("escalation","Use the bedhead algorithm and call the emergency team for peri-arrest or an unresolved blockage.",True,"sourced",GGC),c("documentation","Record checks and care on the tracheostomy chart.",False,"local_protocol")],
 gaps=["The guideline is one NHS board's document, past its review date (November 2024); numerical values (cleaning interval, cuff range, suction duration and vacuum) are marked partial and unit policy governs.","The NTSP algorithms themselves, which the guideline reproduces with permission, were not read from the NTSP; the AARC 2021 CPG, the NSW ACI guide and the Open RN chapters were not accessible.","Decannulation, speaking valves, cuff deflation, tube changes and paediatric care: not drafted (sections not read).","Open RN via NCBI and the eCampusOntario open textbook returned browser-verification or HTTP 403 and were not read; no workaround was attempted."],
 permissions=["NHSGGC guideline: no reuse statement on the file; NTSP resources are reproduced there with permission that does not extend to others; paraphrase only.","AARC CPG and NSW ACI guide: permission or licence verification needed.","Open RN (CC BY): reuse with attribution once a person can retrieve the text."],
 references=[]))
# 13 chest drain --------------------------------------------------------------------------------
write(13,"chest-drain-monitoring",dict(title="Chest drain monitoring", category="elimination-drains", topic_drafts=[],
 evidence_status="partial", license_status="permission_required",
 sources=[src(BTS,"full","BTS Clinical Statement on pleural procedures (2023): practice-point summaries for insertion, bottle/underwater-seal set-up and suction read in full text; narrative review, UK adults, not GRADE"),src("N-NCBI-OPENRN-CHEST","not_read","Open RN via NCBI Bookshelf NBK594490: browser-verification page; not read"),src("N-OPENRN-ADV-PDF","not_read","Open RN Advanced Skills PDF: HTTP 403; not read")],
 objectives=["Keep the drain system below the insertion site, upright and sealed with adequate water.","Check and document drainage, swinging and bubbling on a dedicated observation chart.","Know when drainage or suction must not proceed without specialist or prescriber instructions.","Escalate chest pain, persistent cough or worsening breathlessness."],
 prerequisites=["Respiratory assessment","Infection prevention (SK-21)"],
 sections={
  "indications":sec("local_protocol",LOCAL("The decision to insert, drain, suction or remove a chest drain is a medical or specialist decision; follow the inserting team's written instructions.")),
  "safety":sec("partial",it("Keep the drain bottle below the insertion site at all times and keep the drain upright at all times.","partial",BTS),it("The system must contain adequate water to cover the end of the tube.","partial",BTS),it("Use aseptic non-touch technique when changing a drain bottle, underwater-seal drain or drain tubing.","partial",BTS),it("Avoid clamping a bubbling chest tube unless under specialist pleural supervision and in specific circumstances only.","partial",BTS),it("Drainage of a large pleural effusion should be controlled to prevent re-expansion pulmonary oedema; a drain placed for effusion should be clamped promptly in a patient with repetitive coughing or chest pain, because re-expansion pulmonary oedema is potentially fatal.","partial",BTS),it("Avoid suction soon after insertion; suction pressures should be prescribed or documented by the medical team before suction starts, with the unit using one consistent unit of pressure; routine thoracic suction should be avoided given a lack of data showing benefit.","partial",BTS)),
  "responsibilities":sec("partial",it("Instructions on clamping and the rate of fluid drainage must be given and recorded, and the volume to drain over a specified period should be stated in the procedure report and handover.","partial",BTS)),
  "scope":sec("partial",it("Insertion, suction prescription and decisions about clamping are medical or specialist responsibilities; nursing responsibilities are observation, maintenance of the system as above, documentation and escalation. The source is a UK adult secondary-care clinical statement, not an ICU nursing standard.","partial",BTS)),
  "equipment":sec("local_protocol",LOCAL("Drain type (bottle, digital, ambulatory) and suction equipment follow the unit's supplies and the manufacturer's instructions.")),
  "assessment":sec("partial",it("Check the drain daily for wound infection, fluid drainage volume and the presence of respiratory swinging and/or bubbling, and document them on a dedicated chest drain observation chart.","partial",BTS),it("A follow-up chest radiograph within a few hours of insertion checks drain position (a team decision).","partial",BTS)),
  "monitoring":sec("partial",it("Record drainage volume over time, swinging and bubbling, and the patient's breathing, pain and cough.","partial",BTS)),
  "escalation":sec("partial",it("Report chest pain, persistent cough, worsening breathlessness, new or increased bubbling, drain displacement or disconnection promptly, and do not clamp without instruction.","partial",BTS)),
  "complications":sec("partial",it("Re-expansion pulmonary oedema, drain fall-out (hence the holding suture), infection at the wound.","partial",BTS)),
  "documentation":sec("partial",it("Use the dedicated observation chart for drainage volumes, swinging and bubbling, and record clamping and suction instructions.","partial",BTS)),
  "procedure":sec("local_protocol",LOCAL("Bottle changes, suction connection, troubleshooting a blocked or leaking system and drain removal follow the unit's approved procedure; the practice points read do not give the steps."))},
 checklist=[c("preparation","Confirm the written instructions for this drain (clamping, rate of drainage, suction) before any care.",True,"partial",BTS),c("assessment","Check the drain system is below the insertion site, upright, sealed and has adequate water.",True,"partial",BTS),c("assessment","Check the wound, the drainage volume and swinging or bubbling, and record them on the observation chart.",True,"partial",BTS),c("procedure","Use aseptic non-touch technique when changing the bottle or tubing.",False,"partial",BTS),c("procedure","Do not clamp a bubbling drain and do not start or change suction without instruction.",True,"partial",BTS),c("escalation","Report chest pain, persistent cough, worsening breathlessness or a displaced or disconnected drain at once.",True,"partial",BTS),c("documentation","Record drainage, swinging, bubbling and instructions given.",False,"partial",BTS)],
 gaps=["Interpretation of bubbling and swinging, troubleshooting and drain removal: not in the practice points read.","ICU post-surgical and trauma drains, digital devices and ambulatory systems: not covered here.","Supplemental appendices of the BTS statement (set-up and suction detail): not read.","The Open RN chapter (NBK594490) was not retrievable; no workaround was attempted."],
 permissions=["BTS clinical statement: licence line says no commercial re-use; paraphrase and cite only.","Open RN (CC BY): reuse with attribution once a person can retrieve the text."],
 references=[]))
# 16 mobilisation --------------------------------------------------------------------------------
write(16,"safe-patient-mobilization",dict(title="Safe patient mobilization", category="skin-mobility-transport", topic_drafts=[],
 evidence_status="partial", license_status="unassessed",
 sources=[src(HOD,"full","Hodgson 2014 consensus on safety criteria for active mobilization of mechanically ventilated adults (CC BY 4.0); Figures 2-5 not read"),src("S-SCCM-ABCDEF","partial","ICU Liberation (A-F) bundle page: RED licence; permission required"),src("S-SCCM-PADIS","partial","PADIS: summary only")],
 objectives=["Check airway position and oxygen supply before each mobilization episode.","Know the consensus safety considerations and that they are a guide, not a rule.","Consult the experienced team when several limits are reached."],
 prerequisites=["Pressure injury prevention (SK-14)","Endotracheal tube care (SK-04)"],
 sections={
  "indications":sec("partial",it("The consensus covers active mobilization of adult mechanically ventilated ICU patients; no guidance was developed for passive mobilization. Intubation via an endotracheal tube is not in itself a contraindication to early mobilization.","sourced",HOD)),
  "safety":sec("partial",it("Respiratory criteria the group agreed were safe for in- and out-of-bed mobilization when no other contraindication exists: FiO2 below 0.6, SpO2 above 90% and respiratory rate below 30 breaths per minute (2014 expert consensus).","sourced",HOD),it("If the patient is at the safety limits for several categories at once (for example low SpO2, high FiO2 and high PEEP), consult an experienced medical team before mobilizing.","sourced",HOD),it("Vasoactive drugs are not an absolute contraindication; appropriateness depends on the dose, on the change in dose (rising doses call for caution or contraindicate mobilization) and on whether the patient is clinically well perfused. The panel could not agree a threshold dose, so each unit decides case by case with the ICU team.","sourced",HOD)),
  "responsibilities":sec("partial",it("Before each mobilization episode an appropriate healthcare professional, according to the unit's procedures, checks that any artificial airway (orotracheal, nasotracheal or tracheostomy tube) is correctly positioned and secure, and that supplemental oxygen is available with a reserve exceeding the expected duration of the activity.","sourced",HOD)),
  "scope":sec("partial",it("The criteria are a guide, are appropriate for experienced ICU clinicians, must be used with clinical judgement, and each ICU should consider them against its own staffing and expertise.","sourced",HOD)),
  "assessment":sec("partial",it("The consensus groups safety considerations into respiratory, cardiovascular, neurological (level of consciousness, delirium, intracranial pressure) and other (lines, surgical or medical conditions) categories; the detailed neurological, cardiovascular and other thresholds are in figures that were not read.","partial",HOD)),
  "procedure":sec("local_protocol",LOCAL("Mobilization technique, equipment, staff numbers and progression follow the physiotherapy plan, the unit's approved procedure and manual-handling policy; the consensus does not give steps.")),
  "monitoring":sec("partial",it("Monitor SpO2, respiratory rate, haemodynamics, level of consciousness and symptoms during and after activity against the unit's criteria.","partial",HOD)),
  "escalation":sec("partial",it("Stop and call for help if the patient becomes unstable or reaches the unit's safety limits.","partial",HOD)),
  "documentation":sec("local_protocol",LOCAL("Record the activity, criteria checked, tolerance and any adverse event per unit standard."))},
 checklist=[c("preparation","Confirm the mobilization plan and the unit's safety criteria with the team and physiotherapist.",True,"local_protocol"),c("preparation","Check that any artificial airway is correctly positioned and secure.",True,"sourced",HOD),c("preparation","Confirm oxygen is available with a reserve longer than the planned activity.",True,"sourced",HOD),c("assessment","Check respiratory, cardiovascular and neurological status against the unit's criteria; at the limits in several categories, consult the experienced medical team first.",True,"sourced",HOD),c("assessment","Consider the vasoactive dose, any recent change in dose and whether the patient is well perfused.",True,"sourced",HOD),c("monitoring","Monitor SpO2, respiratory rate, haemodynamics and symptoms during and after.",False,"partial",HOD),c("escalation","Stop and call for help if the patient becomes unstable.",True,"partial",HOD),c("documentation","Record activity, criteria checked and tolerance.",False,"local_protocol")],
 gaps=["The detailed criteria tables (Figures 2-5) are images and were not read; the cardiovascular, neurological and other thresholds are therefore not drafted.","The 2014 consensus is dated and states no agreed vasoactive dose threshold; unit policy governs.","Passive mobilization, rehabilitation progression and manual-handling standards: not covered.","ICU Liberation bundle material: permission required and not used."],
 permissions=["Hodgson 2014: CC BY 4.0, attribution required (GREEN).","SCCM ICU Liberation / PADIS: permission required."],
 references=[]))
# 17 CRRT ---------------------------------------------------------------------------------------
write(17,"crrt-circuit-monitoring",dict(title="CRRT circuit monitoring", category="renal-support", topic_drafts=["D04-T09"],
 evidence_status="partial", license_status="permission_required",
 sources=[src("S-KDIGO-AKI-2012","partial","KDIGO 2012: prescribing guideline; summary of Section 5 statements read"),src(AHS,"full","AHS Dialyzing Wisely CRRT alarm pathway (Jan 2025), device-specific (PrisMax), read in full"),src("N-BAXTER-PRISMAFLEX","not_read","manufacturer operator's manual: URL redirects to the Vantive site; not read"),src("S-CHS-CRRT","not_read","hospital procedure: not accessed")],
 objectives=["Know the prescription and check that delivered treatment matches it.","Respond to circuit alarms by checking the patient first and using the device's own instructions.","Know when to return blood, stop treatment, document and notify the prescriber."],
 prerequisites=["Acute kidney injury","Infection prevention (SK-21)"],
 sections={
  "responsibilities":sec("partial",it("Know the prescription (modality, dose, fluid-balance goal, anticoagulation); report interruptions and under-delivery because KDIGO recommends frequent assessment of delivered dose.","partial","S-KDIGO-AKI-2012"),it("Troubleshoot alarms to minimise downtime and optimise delivered (effluent) dose.","partial",AHS)),
  "safety":sec("partial",it("Check the patient first, and review and address the alarm on the screen before clearing it; the alarm off, disable and override buttons decrease alarm sensitivity.","partial",AHS),it("On the device described, the blood pump stops with high-priority (flashing red) alarms; other devices differ.","partial",AHS),it("Confirm the chest radiograph required after internal jugular or subclavian catheter placement has been done and reviewed before first use (KDIGO).","partial","S-KDIGO-AKI-2012"),it("Escalate possible heparin-induced thrombocytopenia promptly for clinical probability assessment. If clinically likely or confirmed, follow the authorized pathway to stop all heparin exposure, including flushes and locks.","partial","S-KDIGO-AKI-2012")),
  "scope":sec("local_protocol",LOCAL("Who may operate and troubleshoot a CRRT machine is set by competency approval and the unit's policy; the pathway itself says actions are according to local practice guidelines.")),
  "equipment":sec("local_protocol",LOCAL("Machine, filter set and bag arrangement are device- and software-specific; use the manufacturer's operator's manual for your unit's software version.")),
  "assessment":sec("partial",it("For access and return alarms, check the patient (coughing, suctioning, moving), whether a line is clamped or kinked, the dialysis catheter (reposition, flush and aspirate, according to local practice) and the blood-flow rate; for flow alarms check clamps and kinks and whether bags touch other objects, leak or sit on the wrong scale.","partial",AHS)),
  "procedure":sec("local_protocol",LOCAL("Priming, set-up, bag changes and alarm-specific actions follow the manufacturer's instructions and the unit's competency programme; the pathway gives device-specific tips only.")),
  "monitoring":sec("partial",it("Monitor haemodynamics, temperature, fluid balance, electrolytes, acid-base results and bleeding.","partial","S-KDIGO-AKI-2012")),
  "escalation":sec("partial",it("If alarms cannot be resolved, assess the patient, notify the treating team and follow the device and local CRRT pathway for ending therapy. Return circuit blood only if the pathway and device instructions permit it for that failure. Document the cause and interruption.","partial",AHS),it("Report bleeding, suspected HIT, access problems, haemodynamic instability and interruptions.","partial","S-KDIGO-AKI-2012")),
  "documentation":sec("local_protocol",LOCAL("Record delivered dose, interruptions, alarms, the reason for stopping and fluid balance per unit standard."))},
 checklist=[c("preparation","Confirm the prescription (modality, dose, fluid-balance goal, anticoagulant) before and during treatment.",True,"partial","S-KDIGO-AKI-2012"),c("assessment","On any alarm, check the patient first, then the lines, clamps, catheter and bags before clearing it.",True,"partial",AHS),c("procedure","Do not use alarm off, disable or override functions to clear an unresolved problem.",True,"partial",AHS),c("procedure","Operate and troubleshoot the circuit only as the manufacturer's documentation and your competency approval allow.",True,"local_protocol"),c("monitoring","Monitor haemodynamics, temperature, fluid balance and bleeding.",True,"partial","S-KDIGO-AKI-2012"),c("escalation","If alarms cannot be resolved, notify the treating team and document the interruption. Return circuit blood only when the device instructions and local pathway permit it.",True,"partial",AHS),c("documentation","Record delivered dose, interruptions and fluid balance.",False,"local_protocol")],
 gaps=["The alarm pathway is specific to one device family (PrisMax) and one health service; it is not a cross-manufacturer standard.","The manufacturer's operator's manuals were located but not read: Baxter's Prismaflex 7.xx manual URL now redirects to the Vantive site, and software versions differ by unit.","Priming, citrate monitoring, drug dosing, weaning and filter-life management: not covered.","KDIGO 2026 update is a draft; the 2012 guideline is over ten years old."],
 permissions=["AHS pathway: licence not stated on the file; verify before reproducing.","Manufacturer documentation: reproduction permission required.","KDIGO: verify reuse terms."],
 references=[]))
# 20 transport ---------------------------------------------------------------------------------
write(20,"patient-transport",dict(title="Intrahospital patient transport", category="skin-mobility-transport", topic_drafts=[],
 evidence_status="partial", license_status="permission_required",
 sources=[src(ICS,"full","ICS Guidance on the Transfer of the Critically Ill Adult, 5th edition (22 April 2026): numbered recommendations 1-88 and Appendix 7 read in full text; UK guidance")],
 objectives=["Prepare and stabilise the patient before transfer and use the unit's checklist.","Maintain monitoring and security of patient and equipment during transfer.","Document the transfer and hand over to the receiving team."],
 prerequisites=["Ventilator safety checks (SK-07)","ECG monitoring (SK-18)","Arterial line care (SK-01)"],
 sections={
  "indications":sec("partial",it("Critically ill patients undergoing transfer are managed as critical care patients, and identical standards apply to intra- and inter-hospital transfers (ICS recommendations 1-2).","sourced",ICS)),
  "safety":sec("partial",it("Resuscitate and stabilise the patient before transfer to reduce the physiological disturbance of movement; patients with actual or anticipated airway, ventilatory or neurological compromise should be intubated and ventilated before transfer (recommendations 58-59).","sourced",ICS),it("Secure the patient to the transfer trolley with a harness or belt system and stow all portable equipment securely (recommendations 77, 79).","sourced",ICS),it("Keep all monitors, ventilator displays and syringe drivers visible to accompanying staff and tie monitoring cables together to form an umbilicus (recommendations 74-75).","sourced",ICS),it("Maintain patient privacy, dignity and temperature (recommendation 66).","sourced",ICS)),
  "responsibilities":sec("partial",it("Staff undertaking transfers must have received specific training and competencies and must not transfer unsupervised until these are met (recommendations 24-25); a risk assessment is completed beforehand and higher-risk patients need two appropriately trained clinical escorts (recommendations 53-55).","sourced",ICS)),
  "scope":sec("local_protocol",LOCAL("Who may escort, the risk-assessment form and the unit's checklist are set by local policy; the guidance is UK (NHS) and is not law elsewhere.")),
  "equipment":sec("partial",it("Take a minimum of two peripheral venous or one multi-lumen central venous access; medication boluses and infusions should be available for at least twice the planned duration of transfer; with a tracheostomy, take spares in line with the National Tracheostomy Safety Project (recommendations 60-61, 65).","sourced",ICS)),
  "preparation":sec("partial",it("Use a checklist for each stage of the transfer; acute hospitals should have an organisation-wide standardised checklist for intra-hospital transfers (recommendations 69-70). The ICS example covers team, airway and breathing, circulation, neurology, GI/GU, medication, packaging, identification wristbands, monitoring and a ready-to-leave check (Appendix 7; adapted from local checklists).","sourced",ICS)),
  "assessment":sec("partial",it("Assess and document neurological status regularly (every 15 minutes for neurosciences patients, every 30-60 minutes for others) (recommendation 63).","sourced",ICS)),
  "procedure":sec("local_protocol",LOCAL("Moving, lifting and connecting equipment, and the exact order of checks, follow the unit's transfer procedure and training.")),
  "monitoring":sec("partial",it("Apply minimum standards of continuous monitoring in every intra- and inter-hospital transfer (recommendation 73); the example checklist lists ECG, SpO2 and non-invasive blood pressure for all patients and capnography, with or without invasive arterial pressure, for intubated patients (Appendix 7).","sourced",ICS)),
  "escalation":sec("local_protocol",LOCAL("Management of deterioration, emergencies and death during transfer (ICS chapter 23) was not read; follow the unit's transfer escalation protocol and call for help.")),
  "documentation":sec("partial",it("Maintain a record of observations and events for every transfer and complete intra-hospital transfers in the patient's notes; copy or transmit the notes and use a transfer letter or handover document (recommendations 64, 76, 81-82).","sourced",ICS)),
  "communication":sec("partial",it("A clinical handover must occur between referring and receiving teams, and on arrival a formal multidisciplinary handover should occur rather than separate medical and nursing conversations (recommendations 67, 84-85); keep patients and next of kin informed at every stage (recommendation 48).","sourced",ICS))},
 checklist=[c("preparation","Complete the unit's transfer risk assessment and standardised intra-hospital checklist.",True,"sourced",ICS),c("preparation","Confirm the escorting team is trained, available and briefed.",True,"sourced",ICS),c("preparation","Confirm the patient is resuscitated and stabilised, and that airway, ventilation and neurological compromise have been addressed before leaving.",True,"sourced",ICS),c("preparation","Confirm venous access, two identification wristbands and infusions sufficient for at least twice the planned duration.",True,"sourced",ICS),c("procedure","Secure the patient with the harness or belt and stow all equipment securely.",True,"sourced",ICS),c("monitoring","Apply the minimum continuous monitoring; keep monitors and pumps visible and tie cables together.",True,"sourced",ICS),c("monitoring","Record observations at the unit's interval, and assess neurological status at the guidance's intervals.",False,"sourced",ICS),c("escalation","Call for help and follow the unit's transfer escalation protocol if the patient deteriorates.",True,"local_protocol"),c("documentation","Complete the transfer record and give a multidisciplinary handover on arrival.",False,"sourced",ICS)],
 gaps=["The guidance is UK (NHS) and covers inter-hospital transfer too; the ICU nurse's role on a given unit may differ.","Chapter 23 (emergencies, deterioration and death during transfer), equipment and medication appendices, and the MRI chapter: not read.","Oxygen reserve calculation (Appendix 1): not reproduced; device-specific.","The example checklist is adapted from local checklists; the unit's own checklist governs."],
 permissions=["ICS guidance: copyright Intensive Care Society, no reuse statement on the file; permission required to reproduce; paraphrase only."],
 references=[]))
